<?php
declare(strict_types=1);session_start();header('Access-Control-Allow-Origin: http://localhost:3000');header('Access-Control-Allow-Credentials: true');header('Access-Control-Allow-Methods: POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type');header('Content-Type: application/json; charset=utf-8');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(204);exit;}require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';$pdo=getDatabaseConnection();requireAdmin($pdo);$d=json_decode(file_get_contents('php://input'),true);$title=trim((string)($d['title']??''));$message=trim((string)($d['message']??''));$uid=$d['user_id']??null;if(!$title||!$message){http_response_code(422);echo json_encode(['success'=>false,'message'=>'title and message are required.']);exit;}try{$pdo->beginTransaction();if($uid===null){$s=$pdo->query("SELECT id FROM users WHERE role='user'");$ids=$s->fetchAll(PDO::FETCH_COLUMN);}else{$ids=[(string)$uid];}$ins=$pdo->prepare("INSERT INTO notifications(user_id,title,message,type) VALUES(:uid,:title,:message,'admin_notice')");foreach($ids as $id)$ins->execute(['uid'=>$id,'title'=>$title,'message'=>$message]);$pdo->commit();echo json_encode(['success'=>true,'sent'=>count($ids)]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to send notifications.']);}
